FIXTURE=/Users/dm/dev/dev/個人開発/HarnessHub/.worktrees/task-20260728-082322-wt-11/eval-log/dev-graph/live-trial-fixtures/system-spec-lp36-merged-r7 && PLUGIN_ROOT=/Users/dm/dev/dev/個人開発/HarnessHub/.worktrees/task-20260728-082322-wt-11/plugins/dev-graph && python3 -c "
import ast, json, os, sys

# Stage 4: Verify no elicitation/compile logic duplication in dev-graph plugin
# Positive controls: run_chunk exists in system-spec-harness, compile_docset exists in system-spec-harness

plugin_root = '$PLUGIN_ROOT'
harness_root = plugin_root.replace('dev-graph', 'system-spec-harness')

# Scan dev-graph for run_chunk / compile_docset
dev_graph_hits = []
for dirpath, _, filenames in os.walk(plugin_root):
    for fn in filenames:
        if not fn.endswith('.py'):
            continue
        fpath = os.path.join(dirpath, fn)
        try:
            with open(fpath) as f:
                content = f.read()
            if 'run_chunk' in content or 'compile_docset' in content:
                dev_graph_hits.append(fpath)
        except:
            pass

# Positive controls: verify functions exist in system-spec-harness
positive_controls = []
for target_fn, target_func in [('apply-spec-transition.py', 'run_chunk'), ('compile-spec-doc.py', 'compile_docset')]:
    found = False
    for dirpath, _, filenames in os.walk(harness_root):
        for fn in filenames:
            if fn == target_fn:
                fpath = os.path.join(dirpath, fn)
                try:
                    with open(fpath) as f:
                        content = f.read()
                    tree = ast.parse(content)
                    for node in ast.walk(tree):
                        if isinstance(node, ast.FunctionDef) and node.name == target_func:
                            found = True
                            break
                except:
                    pass
    positive_controls.append({'function': target_func, 'file': target_fn, 'found_in_harness': found})

result = {
    'dev_graph_duplicates': dev_graph_hits,
    'duplicate_count': len(dev_graph_hits),
    'positive_controls': positive_controls,
    'verdict': 'PASS' if len(dev_graph_hits) == 0 and all(pc['found_in_harness'] for pc in positive_controls) else 'FAIL'
}
print(json.dumps(result, ensure_ascii=False, indent=2))
if result['verdict'] != 'PASS':
    sys.exit(1)
" 2>&1

